 const a=await originalAccepted(x),before=(evidence.before=clockSnapshot(x)),watch=clockObserve(x,'candidate','increment',a);evidence.observations=watch.statements;const plan=await a.control.captureOriginalPrivateRecoveryReplay(a.installation,a.cut,a.source),result=a.control.originalPrivateRecoveryReplayFacts(await a.control.executeOriginalPrivateRecoveryReplay(plan));
 eq(layout+' counted candidate original empty-history replay completes',[result.nativeCleanupCommitted,result.nativeClosedReadbackConfirmed,result.independentReplayConfirmed,result.readyToReopen],[false,true,true,false]);
